insert into public.templates (id, title, mode, duration_s, scenes, script, cover, book_title, default_state, cliffhanger, sort, video) values
  ('moon', '{name} Visits the Moon', 'day', 8, '[{"image":"cover.jpg"}]'::jsonb, '["One night, {name} and {costar} looked up. The moon was waving!","\"Let''s go!\" said {name}, and {costar} flapped hard.","Up past the clouds they flew, faster than a shooting star.","The moon had craters like giant cups of cocoa.","\"Hold on tight, {costar}! The moon is smiling at us!\"","Behind a moon rock, something tiny was glowing…"]'::jsonb, 'cover.jpg', '{name}''s Moon Trip', '{"scene":"moon","outfit":"raincoat","co_star":"nibbs","text":"Hold on tight, {costar}! The moon is smiling at us!"}'::jsonb, 'What did {name} find on the moon?', 1, 'media/moon.mp4'),
  ('ocean', '{name} Under the Sea', 'day', 8, '[{"image":"reel-ocean.jpg"}]'::jsonb, '["{name} took a deep breath and dived into the sparkly sea.","{costar} blew bubbles shaped like stars.","A friendly whale swam by, humming a slow song.","\"Bubbles, bubbles everywhere! Hello, little fish!\"","Far below, a shell was humming back…"]'::jsonb, 'reel-ocean.jpg', '{name} and the Singing Whale', '{"scene":"ocean","outfit":"raincoat","co_star":"nibbs","text":"Bubbles, bubbles everywhere! Hello, little fish!"}'::jsonb, 'Who was singing in the deep blue sea?', 2, 'media/ocean.mp4'),
  ('jungle', '{name} in Dino Jungle', 'day', 8, '[{"image":"reel-jungle.jpg"}]'::jsonb, '["Deep in the jungle, {name} heard a tiny stomp.","{costar} peeked behind a big green leaf.","A baby dino giggled and splashed in the waterfall.","\"Stomp, stomp! A baby dino wants to play!\"","Then the ground went BOOM… and BOOM again."]'::jsonb, 'reel-jungle.jpg', '{name}''s Dino Day', '{"scene":"jungle","outfit":"raincoat","co_star":"nibbs","text":"Stomp, stomp! A baby dino wants to play!"}'::jsonb, 'Whose giant footprints were those?', 3, 'media/jungle.mp4'),
  ('birthday', '{name}''s Birthday Party', 'birthday', 8, '[{"image":"reel-birthday.jpg"}]'::jsonb, '["Balloons floated up as {name} came downstairs.","{costar} had baked a cake (a little wobbly).","Everyone sang, and the candles twinkled.","\"Make a wish, {name}! Then blow really hard!\"","In the corner sat one giant present, wiggling…"]'::jsonb, 'reel-birthday.jpg', '{name}''s Best Birthday', '{"scene":"birthday","outfit":"party","co_star":"nibbs","text":"Make a wish, {name}! Then blow really hard!"}'::jsonb, 'What was inside the biggest present?', 4, 'media/birthday.mp4'),
  ('bedtime-stars', 'Goodnight, Stars', 'bedtime', 8, '[{"image":"spread-03-bedtime.jpg"}]'::jsonb, '["When the sky turned purple, {name} and {costar} counted stars.","Every star gave a tiny, sleepy twinkle.","\"One star, two stars… sleepy stars, goodnight.\"","{costar} tucked in tiny wings and yawned.","Goodnight, {name}. Sweet dreams."]'::jsonb, 'spread-03-bedtime.jpg', '{name}''s Goodnight Stars', '{"scene":"bedtime","outfit":"raincoat","co_star":"nibbs","text":"One star, two stars… sleepy stars, goodnight."}'::jsonb, 'Which star will {name} wish on tonight?', 5, 'media/bedtime-stars.mp4'),
  ('cloud-whale', 'Cloud Whale Lullaby', 'bedtime', 8, '[{"image":"spread-02-whale.jpg"}]'::jsonb, '["A whale made of clouds drifted past {name}''s window.","\"Hop on,\" it whispered. {costar} climbed on too.","\"Breathe in slow… breathe out slow… float like a cloud.\"","They floated over sleepy hills and quiet seas.","Back in bed, {name} smiled. Goodnight."]'::jsonb, 'spread-02-whale.jpg', '{name} and the Cloud Whale', '{"scene":"bedtime","outfit":"raincoat","co_star":"nibbs","text":"Breathe in slow… breathe out slow… float like a cloud."}'::jsonb, 'Where will the cloud whale float next?', 6, 'media/cloud-whale.mp4')
